class Point:
    def __init__(self, x, y):
        self.x, self.y = x, y
    def __eq__(self, other):
        return (self.x, self.y) == (other.x, other.y)
    def __hash__(self):
        return hash((self.x, self.y))   # equal points must give equal hashes

p, q = Point(1, 2), Point(1, 2)
print("p == q:", p == q, "| same hash:", hash(p) == hash(q))
d = {p: "found"}
print("lookup with equal point:", d.get(q))

p.x = 99                                 # mutate a field used by the hash
print("after mutation, d.get(p):", d.get(p))          # hash changed: key is lost
print("still stored, size:", len(d))

class NoHash:
    def __eq__(self, other):
        return True                      # defining __eq__ alone removes __hash__
try:
    {NoHash()}
except TypeError as e:
    print("TypeError:", e)
print("list hashable?", [].__hash__ is not None)

t = (1, [10, 20], "x")
print("tuple:", t, "hashable?", end=" ")
try:
    print(hash(t))
except TypeError as e:
    print("no ->", e)

t[1].append(30)                      # the list inside can still change
print("after inner append:", t)

try:
    t[0] = 5                         # rebinding a slot is not allowed
except TypeError as e:
    print("t[0] = 5 ->", e)

u = ([1], 2)
try:
    u[0] += [9]                      # extends the list, then fails to rebind the slot
except TypeError as e:
    print("u[0] += [9] raised:", e)
print("but u changed:", u)

point = (3, 4)                       # a fixed record: hashable, usable as a key
