class Colliding:
    calls = 0
    def __init__(self, v):
        self.v = v
    def __hash__(self):
        return 42                     # attacker-chosen: every key lands in one chain
    def __eq__(self, other):
        Colliding.calls += 1          # count comparisons done during probing
        return self.v == other.v

class Normal(Colliding):
    def __hash__(self):
        return hash(self.v)

def build(cls, n):
    cls.calls = 0
    d = {}
    for i in range(n):
        d[cls(i)] = i
    return cls.calls

for n in (100, 200, 400):
    print("n =", n, "| colliding eq calls:", build(Colliding, n),
          "| normal eq calls:", build(Normal, n))
# Doubling n about quadruples the colliding cost: O(n^2) total.
# Python randomizes str/bytes hashes per process (SipHash) so attackers cannot
# precompute such keys.
